interface DomainEventPublisher {
  publish(event: DomainEvent): Promise<void>;
}
class PlaceOrder {
  constructor(
    private repo: OrderRepository,
    private events: DomainEventPublisher
  ) {}
  async execute(cmd: PlaceOrderCmd) {
    const order = Order.create(cmd);
    await this.repo.save(order);
    await this.events.publish(new OrderPlaced(order.id));
  }
}

class CreateUserUseCase {
  constructor(
    private db: PrismaClient, private mailer: SendGridClient,
    private logger: WinstonLogger, private cache: RedisClient
  ) {}
  async execute(input: CreateUserInput) {
    this.logger.info('Creating user...');
    const cached = await this.cache.get(input.email);
    if (cached) return JSON.parse(cached);
    const user = await this.db.user.create({ data: input });
    await this.mailer.send(input.email, 'Welcome!');
    return user;
  }
}
